/**
 * Default PR body generated by branch type (feat/, fix/, docs/, chore/).
 * Complies with all mandatory sections required by checkPrTemplate (#306).
 */

export function templateForBranch(branch = '', meta = {}) {
  const b = String(branch).toLowerCase()
  const { number, title } = meta
  const issueRef = number ? `Refs #${number}` : 'N/A'

  if (b.startsWith('feat/') || b.startsWith('feature/')) {
    return `## Summary
- Task: #${number || ''}
- Scope: New feature: ${title || ''}

## Related Issue
${issueRef}

## User Impact
Enables new functionality for users and integrations.

## Verification
- [ ] Tests added/updated
- [ ] Local test run is passing

## Security
No security or breaking changes introduced.

## Documentation
Documentation and design contracts updated.
`
  }

  if (b.startsWith('fix/') || b.startsWith('bugfix/') || b.startsWith('hotfix/')) {
    return `## Summary
- Task: #${number || ''}
- Scope: Bug fix: ${title || ''}

## Related Issue
${issueRef}

## User Impact
Resolves bug and restores expected behavior for users.

## Verification
- [ ] Reproduction verified
- [ ] Regression tests pass

## Security
No security or breaking changes introduced.

## Documentation
Documentation and comments updated as needed.
`
  }

  if (b.startsWith('docs/')) {
    return `## Summary
Documentation update: ${title || ''}

## Related Issue
${issueRef}

## User Impact
Improves clarity and accuracy of documentation.

## Verification
- [ ] Documentation syntax and links verified

## Security
No code or runtime security impact.

## Documentation
Technical documentation updated.
`
  }

  if (b.startsWith('chore/') || b.startsWith('refactor/')) {
    return `## Summary
Maintenance/refactoring: ${title || ''}

## Related Issue
${issueRef}

## User Impact
Internal maintenance without breaking user behavior.

## Verification
- [ ] Existing automated test suite passes

## Security
No security or breaking changes introduced.

## Documentation
Code comments and documentation aligned.
`
  }

  return `## Summary
${title || 'Changes proposed in this pull request.'}

## Related Issue
${issueRef}

## User Impact
Provides intended changes and improvements.

## Verification
- [ ] Verification steps completed

## Security
No security or data loss risks.

## Documentation
Documentation updated.
`
}
